SELECT 'FACILITIES' AS t;
DESCRIBE SELECT * FROM read_parquet('https://data.source.coop/tristangruppwri/soft-commodity-infrastructure/facilities/BR_facilities.parquet') LIMIT 0;
SQL
duckdb < q_schema.sql 2>&1 | head -80

